const html = (v:unknown) => String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
function canonicalPageContent(value:unknown){
 const content=object(value),components=array(content.components).map(object),hero=components.find(component=>component.componentId==="hero.local_service"),cta=components.find(component=>component.componentId==="conversion.cta"),faq=components.find(component=>component.componentId==="content.faq");
 const sections=components.flatMap((component,componentIndex)=>{
  const props=object(component.props),componentId=String(component.componentId||"");
  if(componentId==="content.rich_text")return[{componentIndex,heading:string(props.heading,"Page content"),headingLevel:"h2",bodyHtml:`<p>${html(props.body)}</p>`}];
  if(["service.grid","service.benefits","trust.proof"].includes(componentId)){
   const items=array(props.items).map(object),body=[props.introduction,...items.flatMap(item=>[item.title,item.description])].filter(Boolean).map(item=>`<p>${html(item)}</p>`).join("");
   return[{componentIndex,heading:string(props.heading,"More information"),headingLevel:"h2",bodyHtml:body}];
  }
  if(componentId==="content.process"){
   const steps=array(props.steps).map(object);
   return[{componentIndex,heading:string(props.heading,"How the process works"),headingLevel:"h2",bodyHtml:`<ol>${steps.map(item=>`<li><strong>${html(item.title)}</strong> ${html(item.description)}</li>`).join("")}</ol>`}];
  }
  return[];
 });
 return{
  components,
  hero:{eyebrow:string(object(hero?.props).eyebrow,""),title:string(object(hero?.props).headline,""),summary:string(object(hero?.props).summary,""),buttonLabel:string(object(hero?.props).primaryCtaLabel,"")},
  cta:{title:string(object(cta?.props).heading,""),body:string(object(cta?.props).body,""),label:string(object(cta?.props).buttonLabel,"")},
  sections,
  faqs:array(object(faq?.props).items).map(object),
 };
}
const isMissingRegisteredPageStructure = (reason:string) => /no registered sections|exactly one hero headline|requires (?:hero\.local_service|content\.rich_text|trust\.proof|conversion\.cta)/i.test(reason);
const isRepairableSchemaBlocker = (reason:string) => /schema must use the approved business identity|approved FAQs but no matching FAQPage schema|requires a Service entity in its approved schema|schema must identify its approved market/i.test(reason);
const missingRegisteredPageStructure = (page:Page) => !array(object(page.contentJson).components).length
  || Boolean(page.seoQuality?.blockingReasons.some((reason) => reason.startsWith(`${page.title} `) && isMissingRegisteredPageStructure(reason)));
const registeredPageStructureMessage = (title:string) => `${title} has its SEO plan and search markup, but its visible website sections have not been created yet. Generate the complete page once, review it, then rerun Website Quality Review.`;
const pageApprovalReadiness = (page:Page):ApprovalReadiness => {
 if(page.approvalReadiness)return page.approvalReadiness;
 if(!pageContentComplete(page))return{ready:false,canOverride:false,state:"content_required",reason:"Create the complete registered page content before approval."};
 if(/review capabilities,\s*process,\s*proof,\s*faqs/i.test(String(object(page.seoJson).metaDescription??"")))return{ready:false,canOverride:false,state:"placeholder",reason:"This is an earlier placeholder draft. Regenerate it as complete website content before approval."};
 if(page.seoQuality?.status==="blocked"||page.seoQuality?.status==="revision_required"){
  const failed=page.seoQuality.checks.filter(check=>check.status==="fail").map(check=>check.label).slice(0,3);
  const wasApproved=["approved","deployed","published"].includes(page.status);
  if(page.seoQuality.blockingReasons.some(isMissingRegisteredPageStructure))return{ready:false,canOverride:false,state:"validation_blocked",reason:registeredPageStructureMessage(page.title)};
  return{ready:false,canOverride:page.seoQuality.blockingReasons.length===0,state:"validation_blocked",reason:page.seoQuality.blockingReasons[0]?`${wasApproved?"This page was approved before the latest website quality review. Its release is now blocked":"Approval is blocked"}: ${page.seoQuality.blockingReasons[0]}`:`${wasApproved?"This page was approved earlier, but the latest website quality review found required corrections.":`SEO quality is ${page.seoQuality.score}/100.`} Fix ${failed.length?failed.join(", "):"the highlighted quality checks"} before approval.`};
 }
 if(["approved","deployed","published"].includes(page.status))return{ready:false,canOverride:false,state:"approved",reason:`Version ${page.version} is approved and passes the current page-quality checks.`};
 return{ready:true,canOverride:false,state:"ready",reason:`Version ${page.version} passed the required content and quality checks and is ready to approve.`};
};
const contentPhaseForPage = (page:Page):WebsiteContentGenerationPhase => {
 const authority=object(object(page.briefJson).authorityCluster);
 return page.generationPhase??websiteContentGenerationPhase({pageType:page.pageType,searchIntent:page.searchIntent,authorityClusterRole:String(authority.clusterRole??""),authorityLocation:String(authority.location??""),authorityPageKey:String(authority.pageKey??"")});
};
