function savedWebsiteBuilderStep(response:Response):Step{
 const build=response.build;
 if(!build)return"foundation";
 const activePages=build.pages.filter(page=>page.status!=="deferred");
 const ongoingPublisherActive=response.wordpressPublishingJobs?.some(job=>!["published","cancelled"].includes(job.status))
  &&(build.status==="published"||response.websiteWorkflow.publications.some(publication=>publication.target==="wordpress"&&publication.status==="published"));
 if(ongoingPublisherActive)return"publish";
 const brand=object(build.brandJson),settings=object(build.settingsJson);
 const footer=object(settings.contactDetails);
 const foundationReady=["primaryColor","secondaryColor","accentColor","backgroundColor","textColor","headingFont","bodyFont"].every(key=>String(brand[key]??"").trim())&&["uploaded","url","none"].includes(String(brand.logoMode))&&Boolean(settings.selectedLayout||build.templateKey)&&Boolean(String(footer.phone||"").trim()&&String(footer.email||"").trim());
 if(!foundationReady)return"foundation";
 const seoPlan=object(settings.seoPlan),siteFiles=object(settings.siteFiles);
 if(!seoPlan.sourceTaskId||!activePages.length||!build.sitemapApprovedAt||!siteFiles.approvedAt)return"structure";
 const websiteJob=build.jobs.find(job=>String(object(job.inputJson).mode)==="website_generation");
 const pageVersionSignature=activePages.map(page=>`${page.id}:${page.version}`).join("|");
 const previewCurrent=websiteJob?.status==="completed"
  &&String(object(websiteJob.resultJson).assembledPageVersionSignature||"")===pageVersionSignature
  &&String(object(websiteJob.resultJson).navigationSignature||"")===JSON.stringify(array(settings.menu).map(object));
 if(!previewCurrent){
  const contentReady=activePages.every(page=>pageContentComplete(page)&&["approved","deployed","published"].includes(page.status));
  if(!contentReady)return"content";
  const navigationReady=Boolean(settings.navigationConfirmedAt)&&array(settings.menu).length>0;
  if(!navigationReady)return"menus";
  return"media";
 }
 const workflow=response.websiteWorkflow;
 if(!workflow.validation||workflow.validation.blockingCount>0)return"optimization";
 if(!workflow.release)return"review";
 if(!workflow.launchReadiness||workflow.launchReadiness.blockingCount>0||workflow.launchReadiness.releaseId!==workflow.release.id||workflow.launchReadiness.snapshotHash!==workflow.release.snapshotHash)return"launch";
 return"publish";
}

