   {developmentJob&&<div className={`mt-4 rounded-xl border bg-white p-4 ${developmentJob.status==="failed"?"border-rose-200":"border-indigo-100"}`}><div className="flex items-center justify-between gap-3"><div><b className="text-sm text-slate-900">{developmentJob.status==="queued"?"Website queued":developmentJob.status==="processing"?"Website creation in progress":developmentJob.status==="completed"?"Responsive preview prepared":"Website creation needs attention"}</b><p className="mt-1 text-xs text-slate-500">{developmentJob.stage.replaceAll("_"," ")}{developmentJob.status==="processing"?" · You can continue working elsewhere.":""}</p></div><span className="text-lg font-black text-indigo-700">{developmentJob.progress}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full transition-all ${developmentJob.status==="failed"?"bg-rose-500":"bg-indigo-600"}`} style={{width:`${developmentJob.progress}%`}}/></div>{developmentJob.errorMessage&&<p className="mt-3 text-xs font-semibold text-rose-700">{failedOnDeferredPage?"This attempt used an outdated page selection. The referenced Local Authority page is scheduled for later and will be excluded from the next attempt.":developmentJob.errorMessage}</p>}{developmentJob.status==="failed"&&/required .* page block|fewer than seven registered content blocks|thin page content/i.test(developmentJob.errorMessage||"")&&<p className="mt-2 rounded-lg bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-800">{/thin page content/i.test(developmentJob.errorMessage||"")?"The page will be assembled without artificial filler. Any useful depth recommendation will appear in Quality Review.":"Existing work is preserved. SENuke AI will repair only the missing registered structure and continue creating the review-ready website."}</p>}{developmentJob.status==="failed"&&<button type="button" disabled={busy==="submit-development"} onClick={()=>void submitDevelopment(true,false,automaticWebsiteBuild)} className="mt-3 rounded-lg bg-rose-700 px-4 py-2.5 text-xs font-black text-white disabled:bg-slate-300">{failedOnDeferredPage?"Retry Active Pages Only":/website image generation is incomplete/i.test(developmentJob.errorMessage||"")?"Generate Missing Images & Continue":automaticWebsiteBuild?"Retry Complete Website Creation":/required .* page block|fewer than seven registered content blocks|thin page content/i.test(developmentJob.errorMessage||"")?"Continue with Approved Content":"Retry Website Creation"}</button>}</div>}
