     <h3 className={`mt-1 text-lg font-black ${done("optimization")?"text-emerald-950":websiteWorkflow.validation?.blockingCount?"text-rose-950":"text-amber-950"}`}>{done("optimization")?`Quality review passed · ${websiteWorkflow.validation?.overallScore}/100`:websiteWorkflow.validation?.blockingCount?`${websiteWorkflow.validation.blockingCount} blocking quality findings`:"Check the complete website before approval"}</h3>
