 const content=object(page.contentJson),view=canonicalPageContent(content),seo=object(page.seoJson),brief=object(page.briefJson),sections=view.sections,components=view.components,faqs=view.faqs,keywords=array(seo.metaKeywords).length?array(seo.metaKeywords).map(String):[page.primaryKeyword,...array(page.secondaryKeywords).map(String)],generated=components.length>0,needsStructure=missingRegisteredPageStructure(page),approval=pageApprovalReadiness(page),approvalBusy=busy===`approve-${page.id}`,structureBusy=busy===`structure-repair-${page.id}`,schemaBusy=busy===`schema-repair-${page.id}`,repairableSchemaBlockers=page.seoQuality?.blockingReasons.filter(isRepairableSchemaBlocker)??[];
