 const normalize=()=>initialMenu.flatMap((item,index)=>{const page=pages.find(row=>row.id===String(item.pageId??""))??pages.find(row=>row.slug===String(item.slug??""));const custom=item.custom===true||String(item.pageId??"").startsWith("custom-");if(!page&&!custom)return[];return [{pageId:page?.id??String(item.pageId),label:string(item.label,page?.title??"Menu item"),slug:page?.slug??String(item.slug??""),parentPageId:item.parentPageId?String(item.parentPageId):null,custom,order:index}]});
