 const addCustom=()=>{const label=customLabel.trim();if(!label)return;setItems(current=>[...current,{pageId:`custom-${Date.now()}`,label,slug:customUrl.trim(),parentPageId:null,custom:true}]);setCustomLabel("");setCustomUrl("")};
